<script>
(()=>{
 const forms=[...document.querySelectorAll('form[data-settings-form]')];
 const snapshot=form=>JSON.stringify([...new FormData(form).entries()].filter(([name])=>!['_token','_api_method','_api_endpoint'].includes(name)));
 forms.forEach(form=>{form.dataset.initial=snapshot(form);const changed=event=>{if(event?.target?.name==='providerName'&&event.target.value.trim())event.target.setCustomValidity('');form.dataset.dirty=snapshot(form)!==form.dataset.initial?'yes':'no';};form.addEventListener('input',changed);form.addEventListener('change',changed);form.addEventListener('submit',event=>{if(form.id==='payment-settings-form'&&form.elements.enabled.checked&&!form.elements.providerName.value.trim()){event.preventDefault();form.elements.providerName.setCustomValidity('Enter a provider name before enabling this setting.');form.elements.providerName.reportValidity();return;}if(form.elements.providerName)form.elements.providerName.setCustomValidity('');form.dataset.dirty='no';});form.querySelector('[data-cancel-form]')?.addEventListener('click',()=>{form.reset();form.elements.providerName?.setCustomValidity('');form.dataset.dirty='no';});});
 const dirty=()=>forms.some(form=>form.dataset.dirty==='yes');window.addEventListener('beforeunload',event=>{if(dirty()){event.preventDefault();event.returnValue='';}});document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(!link||!dirty())return;const href=link.getAttribute('href');if(!href||href.startsWith('#')||link.target==='_blank')return;if(!window.confirm('You have unsaved settings changes. Leave this page and discard them?'))event.preventDefault();});
})();
</script></body></html>
